function pjSettingsPage(id){const p=pjProject(id);if(!p)return head('项目设置','项目不存在','请检查项目编号。');pjCurrent=id;const n=pjState.settings[id]||0;return head('项目设置 · '+pjEsc(p.code),pjEsc(p.name),'配置仅在浏览器内存中生效，刷新恢复样例。')+`<div class="tabs row wrap" role="tablist" aria-label="项目设置">${pjSettingsLabels.map((t,i)=>`<button role="tab" aria-selected="${i===n}" class="${i===n?'on':''}" onclick="pjSettingsTab('${id}',${i})">${t}</button>`).join('')}</div><div id="pj-settings-body" role="tabpanel">${pjSettingsPanel(p,n)}</div>`;}
