 if(n===6)blocks=[card('甲方可见性',pjKV([['概览','仅里程碑级'],['需求确认单','版本与签收'],['变更','范围、日期、价格与确认'],['交付与验收','已接受交付包与甲方批注'],['预览与产物','仅面向甲方的项目'],['问题反馈','提交问题，由团队分流到内部缺陷']])),card('AI 协作标签',`<label class="row"><input type="checkbox" ${p.ai?'checked':''} ${ro?'disabled':''} onchange="pjVisibilitySave('${p.id}',this.checked)">展示 AI 协作标签</label><div class="note info">${p.ai?'由 AI 与工程师协作完成':'项目交付由团队负责'}</div><p class="muted xs">标签不改变甲方的数据访问范围。${ro?'项目已结束，只读。':''}</p>`),card('共享频道与内部边界',pjKV([['甲方沟通','人工创建共享频道，明确标注「甲方在此频道」'],['Agent 消息','默认需你批准；范围、日期、价格与承诺仅人发送'],['甲方不可见','任务、评审台、流水线、执行、内部验收、内部缺陷、内部频道、Agent 内部信息、目标与计划'],['内部旁注','始终不向甲方展示']]))];
