function pjVisibilitySave(id,v){const p=pjProject(id);if(pjReadonly(p))return toast('项目只读');p.ai=v;pjEvent(p,'更新甲方 AI 协作标签');route();toast('已保存（演示）');}
function pjConstitutionPreview(id){const p=pjProject(id);openDrawer(card('项目宪法配置',pjKV([['项目',pjEsc(p.code)],['版本',p.constitution?'v'+p.constitution:'未配置'],['构建 / 测试命令','未配置'],['约束 / 禁区','未配置'],['preview 块','启动命令、端口、健康检查路径未配置']])+pjButton('关闭','closeDrawer()','ghost')));}
function pjAutonomy(id){const p=pjProject(id);pjModal('自治级别',pjSelect('级别','pj-autonomy',[['低','低'],['中','中'],['高','高']],p.autonomy||'低')+'<div class="note info">中高风险或自治级别 ≥ 中，执行前必须审批计划。</div>',pjButton('取消','closeModal()')+pjButton('保存',`pjAutonomySave('${id}')`,'primary'));}
function pjAutonomySave(id){const p=pjProject(id),v=pjVal('pj-autonomy');if(pjReadonly(p)||!['低','中','高'].includes(v))return pjError('无法保存自治级别');p.autonomy=v;pjEvent(p,'更新自治级别');closeModal();route();}
function pjSaveSettings(id){const p=pjProject(id),name=pjVal('pj-name');if(pjReadonly(p))return toast('项目只读');if(!name||name.length>200)return toast('名称必填，最多 200 字');if(pjProjects.some(x=>x.id!==id&&x.client===p.client&&x.name===name))return toast('同甲方下已存在同名项目');p.name=name;p.description=pjVal('pj-description');p.target=pjVal('pj-target');pjEvent(p,'更新项目基本信息');pjRefresh();toast('已保存基本信息（演示）');}
function pjContact(id){const p=pjProject(id);if(pjReadonly(p)||p.contacts&&pjDeliveries.some(d=>d.p===id&&d.s==='SENT'))return toast('待验收交付需要保留可签收联系人。');pjModal(p.contacts?'移除联系人':'添加联系人',`<div class="note ${p.contacts?'danger':'info'}">${p.contacts?'移除后没有可签收联系人，无法正式交付；保留历史回执。':'使用本项目外部成员账户作为主联系人，默认接收交付且可签收。'}</div>${p.contacts?pjStepup('移除联系人'):''}<p>${pjEsc(p.client)}</p>`,pjButton('取消','closeModal()')+pjButton('确认',`pjContactSave('${id}')`,p.contacts?'danger':'primary'));}
function pjContactSave(id){const p=pjProject(id);if(p.contacts&&!document.getElementById('pj-stepup').checked)return pjError('需重新认证');if(pjReadonly(p)||p.contacts&&pjDeliveries.some(d=>d.p===id&&d.s==='SENT'))return pjError('不能移除最后可签收联系人。');p.contacts=!p.contacts;pjEvent(p,'更新甲方联系人');closeModal();pjRefresh();}
function pjStepup(action){return `<div class="note warn">${I('fingerprint')}需重新认证。原型仅模拟身份验证，不会进行真实认证或调用服务。</div><label class="row"><input type="checkbox" id="pj-stepup">你已完成重新认证（演示） · ${action}</label>`;}
function pjBudget(id){const p=pjProject(id);pjModal('调整预算上限',`${pjField('预算上限（美元，两位小数）','pj-cap',Number.isFinite(p.budget[1])?p.budget[1].toFixed(2):'','number','min="0.01" step="0.01"')}${pjField('通知阈值（50–95）','pj-notify',p.notify||80,'number','min="50" max="95"')}${pjField('修改理由','pj-reason')}<p class="small">当前已花费 ${money(p.budget[0])}。降低到已花费以下将暂停新执行；提高上限只解除预算暂停，不解除其他升级暂停。</p>${pjStepup('预算上限修改')}`,pjButton('取消','closeModal()')+pjButton('验证身份并保存',`pjBudgetSave('${id}')`,'primary'));}
function pjBudgetSave(id){const p=pjProject(id),cap=Number(pjVal('pj-cap')),n=Number(pjVal('pj-notify'));if(pjReadonly(p))return pjError('项目只读。');if(!/^\d+(\.\d{1,2})?$/.test(pjVal('pj-cap'))||!Number.isFinite(cap)||cap<=0||!Number.isInteger(n)||n<50||n>95)return pjError('预算须大于零且最多两位小数，通知阈值须为 50–95 的整数。');if(!pjVal('pj-reason'))return pjError('请填写预算修改理由。');if(!document.getElementById('pj-stepup').checked)return pjError('需先完成重新认证（演示）。');p.budgetEvents=p.budgetEvents||[];p.budgetEvents.unshift(money(p.budget[1])+' → '+money(cap)+' · '+pjVal('pj-reason'));p.budget[1]=cap;p.notify=n;pjEvent(p,'调整预算上限为 '+money(cap));closeModal();pjRefresh();toast('预算已保存；其他暂停原因保持有效');}
function pjModeChecks(p){return [
 ['P1','有效裁决委托、运行中评审 Agent、剩余至少 24 小时',false],
 ['P2','预算、验证无定论、甲方拒收、返工上限四类升级规则',true],
 ['P3','有限预算上限，且尚未耗尽',Number.isFinite(p.budget[1])&&p.budget[1]>p.budget[0]],
 ['P4','至少一名具有项目执行角色的运行中 Agent',p.members.some(k=>PEOPLE[k].role==='Agent 执行者'&&PEOPLE[k].origin!=='orphan'&&MACHINES.some(m=>m.st==='ONLINE'&&m.agents.includes(k)))],
 ['P5','规划、进行中或待验收阶段',['PLANNING','ACTIVE','ACCEPTANCE_PENDING'].includes(p.stage)]];}
function pjMode(id){const p=pjProject(id);pjModal('切换模式',pjSelect('目标模式','pj-mode-target',[['HYBRID','混编'],['AUTONOMOUS','全自治'],['HUMAN_ONLY','纯人工 + AI 协助']],p.mode)+`<div class="note danger">切换改变派单与裁决路径。离开全自治撤销项目委托并改为人工派单；纯人工停止向 Agent 派发执行、测试、验收与评审，释放未开始的 Agent 分派；运行中的执行可跑完。需重新认证。</div><p class="muted small">仅团队所有者具有模式切换权限；当前演示操作人：Sam。</p>${pjModeChecks(p).map(c=>`<div class="note ${c[2]?'ok':'warn'}">${c[0]} · ${c[1]} · ${c[2]?'满足':'未满足'}</div>`).join('')}<p class="muted xs">尚无有效委托快照，不能提交全自治切换；纯人工须先切回混编才能进入全自治。</p>${pjField('切换理由（至少 10 个字）','pj-reason')}${pjStepup('团队模式切换')}`,pjButton('取消','closeModal()')+pjButton('验证身份并切换',`pjModeSave('${id}')`,'danger',pjReadonly(p)));
 const select=document.getElementById('pj-mode-target');if(select)select.onchange=()=>pjModeAvailability(id);pjModeAvailability(id);
}
function pjModeAvailability(id){const p=pjProject(id),target=pjVal('pj-mode-target'),modal=document.getElementById('modal');if(!modal)return;const button=modal.querySelector('button.danger');if(!button)return;const reason=pjReadonly(p)?'项目已结束，只读':target===p.mode?'请选择不同的目标模式':target==='AUTONOMOUS'&&p.mode==='HUMAN_ONLY'?'纯人工须先切回混编':target==='AUTONOMOUS'&&!pjModeChecks(p).every(c=>c[2])?'全自治 P1–P5 未全部满足':'';button.disabled=!!reason;pjError(reason);}
function pjModeSave(id){const p=pjProject(id),target=pjVal('pj-mode-target');if(pjReadonly(p)||!['HYBRID','AUTONOMOUS','HUMAN_ONLY'].includes(target)||target===p.mode)return pjError('请选择可切换的目标模式');if(target==='AUTONOMOUS'&&(p.mode!=='HYBRID'||!pjModeChecks(p).every(c=>c[2])))return pjError('全自治前置条件未满足');if(pjVal('pj-reason').length<10||!document.getElementById('pj-stepup').checked)return pjError('需填写至少 10 个字的理由，并重新认证');
 if(p.mode==='AUTONOMOUS'){p.policy='MANUAL';p.delegationsRevoked=true;}
 if(target==='HUMAN_ONLY'){p.policy='MANUAL';pjWork.filter(w=>w.p===id&&PEOPLE[w.who]?.k==='a'&&['READY','CLAIMED'].includes(w.s)).forEach(w=>{w.s='READY';w.who=null;});}
 p.mode=target;pjEvent(p,'切换模式为 '+({HYBRID:'混编',AUTONOMOUS:'全自治',HUMAN_ONLY:'纯人工 + AI 协助'})[target]);closeModal();route();toast('模式已切换（内存演示）');}
function pjDanger(id,kind){const p=pjProject(id),cancel=kind==='cancel',count=pjWork.filter(w=>w.p===id&&!['ACCEPTED','CANCELLED'].includes(w.s)).length;pjModal(cancel?'终止项目':'归档项目',`<div class="note danger">${cancel?`将取消 ${count} 个未结束工作项，停止关联活跃执行，撤销本项目委托；保留已经接受的工作与历史证据。`:'将从默认项目列表隐藏项目，所有历史资料保持只读。'}操作将留下审计记录。</div>${pjField('输入项目代号 '+p.code+' 确认','pj-confirm')}${pjField('操作理由（至少 10 个字）','pj-reason')}${pjStepup(cancel?'终止项目':'归档项目')}`,pjButton('返回','closeModal()')+pjButton('验证身份并'+(cancel?'终止':'归档'),`pjDangerSave('${id}','${kind}')`,'danger'));}
function pjDangerSave(id,kind){const p=pjProject(id);if(kind==='archive'&&!['CLOSED','CANCELLED'].includes(p.stage)||kind==='cancel'&&pjReadonly(p))return pjError('当前阶段不允许此操作。');if(pjVal('pj-confirm')!==p.code||pjVal('pj-reason').length<10||!document.getElementById('pj-stepup').checked)return pjError('请正确输入代号、至少 10 个字的理由，并完成重新认证。');if(kind==='cancel'){p.stage='CANCELLED';pjWork.filter(w=>w.p===id&&!['ACCEPTED','CANCELLED'].includes(w.s)).forEach(w=>w.s='CANCELLED');}else p.archived=true;pjEvent(p,kind==='cancel'?'终止项目':'归档项目');closeModal();route();toast('已完成（原型演示，刷新恢复）');}

/* 需求基线与范围变更 */
PAGES['requirement']=(id)=>{const r=pjRequirements.find(x=>x.id===id);if(!r)return head('需求','需求不存在','当前原型尚未包含这条需求。',pjButton('返回项目',"go('project/'+(typeof CURPROJ!=='undefined'?CURPROJ:'p1'))"));pjReqId=id;pjReqTab=0;pjPreview='正常';return head('项目需求 · '+id,r.title,`${TEAM.name} · 当前基线 v${r.version} · 修改必须发起范围变更`,pjButton('返回项目',`go('project/${r.p}')`)+pjButton('发起范围变更',`pjScope('${id}')`,'danger',id!=='R-12'||pjReadonly(pjProject(r.p)),id!=='R-12'?'当前演示仅提供 R-12 的标准明细':''))+pjTabs(['基线与验收标准','版本时间线与对比','关联工作项'],0,'pjRequirementTab')+`<div class="row wrap" style="margin:12px 0"><span class="muted small">状态预览</span>${['正常','空','错误','无权限'].map(s=>`<button class="chip ${s===pjPreview?'on':''}" type="button" onclick="pjPreviewSet(this,'${s}')">${s}</button>`).join('')}</div><div id="pj-requirement-body">${pjRequirementBody()}</div>`;};
TITLES['requirement']='需求详情';NAVPARENT['requirement']='requirements';
function pjRequirementTab(btn,index){pjReqTab=index;btn.parentNode.querySelectorAll('button').forEach((b,i)=>b.classList.toggle('on',i===index));pjReqRefresh();}
function pjPreviewSet(btn,state){pjPreview=state;btn.parentNode.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.textContent===state));pjReqRefresh();}
function pjReqRefresh(){const el=document.getElementById('pj-requirement-body');if(el){el.innerHTML=pjRequirementBody();pjIcons();}}
function pjCoverage(c){return c.items.some(id=>pjWork.find(w=>w.id===id&&w.s==='ACCEPTED'&&!w.stale));}
function pjRequirementBody(){const r=pjRequirements.find(x=>x.id===pjReqId),p=pjProject(r.p);if(pjPreview==='空')return card('需求基线','<div class="empty">还没有验收标准。你可以在草稿阶段补充标准，再基线化。</div>');if(pjPreview==='错误')return card('读取失败',`<div class="note danger">暂时无法读取需求基线，你的修改没有提交。</div>${pjButton('重试',"route()",'primary')}`);if(pjPreview==='无权限')return card('访问受限','<div class="note warn">你没有查看此需求的权限，请联系项目交付负责人。</div>');if(r.id!=='R-12')return `<div class="stack">${card('需求基线',`<dl class="kv"><dt>版本</dt><dd>v${r.version}</dd><dt>验收标准</dt><dd>${r.standards} 条</dd><dt>优先级</dt><dd>${r.priority}</dd></dl>`)}${card('关联工作项',pjWorkRows(p,'').replace('项目工作项','关联工作项'))}${card('来源来件',`<a href="#/baseline/${r.p}">${r.intake} · ${r.source}</a><p class="muted small">主文件未提供这条需求的逐条验收标准，不编造内容。</p>`)}</div>`;
 if(pjReqTab===1)return pjVersionView(r);
 if(pjReqTab===2)return `<div class="stack">${card('关联工作项',pjTable(['工作项','状态','基线','关联标准'],pjWork.filter(w=>w.requirement===r.id).map(w=>`<tr><td><a href="#/workitem/${w.id}">${w.id} · ${pjEsc(w.t)}</a></td><td>${S(w.s)}</td><td>${w.baseline} ${w.stale?'<span class="badge b-warn">基线过期</span>':''}</td><td>${pjCriteria.filter(c=>c.items.includes(w.id)).map(c=>c.code).join('、')||'未关联'}</td></tr>`).join('')))}${card('过期基线处理','<div class="note warn">被范围变更标记过期的工作项必须重新对照当前验收标准验证、裁决，不能直接进入交付包。</div>')}${card('来源与拆解','<p>这些工作项属于同一需求基线；依赖应保留在同项目内。验收标准覆盖由已接受工作项决定。</p>')}</div>`;
 return `<div class="grid g12"><div class="c8 stack">${card('基线描述',`<p>${pjEsc(r.description||'财务人员按账期导出 CSV，字段与甲方模板一致，金额按行项目舍入，失败时提供重试提示。')}</p><div class="note info">已基线 v${r.version}，只读。修改需发起范围变更；Agent 已声明完成（未验证），不代表标准已被覆盖。</div>`)}${card('验收标准',pjTable(['标准','内容','必需 / 引入','关联工作项','覆盖状态'],pjCriteria.map(c=>`<tr><td class="mono">${c.code}</td><td>${pjEsc(c.text)}</td><td>是 · v${c.since}</td><td>${c.items.map(id=>`<a href="#/workitem/${id}">${id}</a>`).join('<br>')}</td><td>${S(pjCoverage(c)?'PASSED':c.items.length?'IN_PROGRESS':'PENDING',pjCoverage(c)?'已被接受工作项覆盖':c.items.length?'进行中':'无工作项')}</td></tr>`).join('')),{icon:'list-checks'})}</div><div class="c4 stack">${card('覆盖率',`<b>${(pjCriteria.filter(pjCoverage).length/pjCriteria.length*100).toFixed(1)}%</b><p>${pjCriteria.filter(pjCoverage).length} / ${pjCriteria.length} 条必需标准被已接受工作项覆盖</p><div class="progress"><i style="width:${pjCriteria.filter(pjCoverage).length/pjCriteria.length*100}%"></i></div><p class="muted xs">这里只计算验收标准覆盖，不是证据覆盖或项目工作项接受率。</p>`)}${card('来源来件',`<a href="#/baseline/${r.p}">${r.intake} · ${r.source}</a><dl class="kv"><dt>甲方联系人</dt><dd>${who('lee')}</dd><dt>开口</dt><dd>共享频道</dd><dt>关联项目</dt><dd><a href="#/project/p1">账单中心</a></dd></dl>`)}${card('授权边界','<div class="note warn">范围变更只能由有范围变更权限的人重新认证后提交，不可委托给 Agent。</div>')}</div></div>`;
}
function pjScope(id){const r=pjRequirements.find(x=>x.id===id);if(id!=='R-12'||pjReadonly(pjProject(r.p)))return toast('当前需求不可发起演示范围变更');pjModal('发起范围变更 · 基于 v'+r.version,`<div class="grid g12"><div class="c6 stack">${pjField('需求标题','pj-scope-title',r.title)}${pjField('描述','pj-scope-description',r.description)}${pjSelect('优先级','pj-scope-priority',[['高','高'],['中','中'],['低','低']],r.priority)}${pjSelect('标准修改方式','pj-scope-kind',[['add','新增'],['retire','退役'],['rewrite','改写（替换）']],'rewrite')}${pjSelect('受影响标准','pj-scope-criterion',pjCriteria.map(c=>[c.code,c.code+' · '+c.text]),'C7')}${pjField('新增 / 改写后的标准文本','pj-scope-text','金额显示币种并保留两位小数')}${pjButton('计算影响预览','pjScopePreview()','sm')}</div><div class="c6 stack"><div id="pj-scope-impact">${pjScopeImpact('C7','rewrite')}</div>${pjField('变更摘要（必填）','pj-scope-summary')}${pjField('理由（必填）','pj-reason')}${pjField('来源来件（可选）','pj-scope-source',r.intake)}${pjStepup('范围变更')}<div class="note danger">新基线将使受影响工作项过期，或按你的选择取消；取消会停止该项执行，证据与审计保留。提交需重新认证。</div></div></div>`,pjButton('取消','closeModal()')+pjButton('验证身份并提交',`pjScopeSave(${r.version})`,'danger'),true);}
function pjScopeImpact(code,kind){const c=pjCriteria.find(c=>c.code===code),ids=kind==='add'?[]:c?c.items:[];return `<b>影响预览</b><div id="pj-impact-meta" data-code="${code}" data-kind="${kind}"></div>${ids.length?ids.map(id=>`${pjSelect(id+' · '+pjWork.find(w=>w.id===id).t,'pj-impact-'+id,[['stale','标记过期'],...(!['ACCEPTED','CANCELLED'].includes(pjWork.find(w=>w.id===id).s)?[['cancel','取消']]:[])],'stale')}${pjWork.find(w=>w.id===id).s==='ACCEPTED'?'<span class="muted xs">已接受工作项只标记过期，不改变状态；新范围须新建工作项或走返工来件。</span>':''}`).join(''):'<div class="note info">新增标准暂无关联工作项，覆盖状态为「无工作项」。</div>'}<p class="muted xs">退役与改写只影响该标准关联的工作项；每个受影响项必须逐项选择。</p>`;}
function pjScopePreview(){document.getElementById('pj-scope-impact').innerHTML=pjScopeImpact(pjVal('pj-scope-criterion'),pjVal('pj-scope-kind'));}
function pjVersionView(r){const versions=pjVersions.map(v=>[String(v.version),'v'+v.version]);return `<div class="grid g12"><div class="c4">${card('基线版本时间线',`<div class="stack">${[...pjVersions].reverse().map(v=>`<div><b>v${v.version} · ${v.at}</b><p class="small">${v.criteria.length} 条生效标准 · ${pjEsc(v.title)}</p><span>${v.record} · Morgan 授权裁决</span></div>`).join('')}</div>`,{icon:'history'})}</div><div class="c8 stack">${card('版本对比',`<div class="row wrap">${pjSelect('旧版本','pj-version-old',versions,String(Math.max(1,r.version-1)))}${pjSelect('新版本','pj-version-new',versions,String(r.version))}${pjButton('对比','pjCompareVersions()','primary sm')}</div><div id="pj-version-diff">${pjVersionDiff(Math.max(1,r.version-1),r.version)}</div>`,{icon:'git-compare'})}${card('版本影响','<p>退役标准保留在历史基线中；改写通过新增替换标准表达。受影响工作项必须重新验证与裁决，不能静默沿用旧基线。</p>')}</div></div>`;}
function pjVersionDiff(from,to){const a=pjVersions.find(v=>v.version===Number(from)),b=pjVersions.find(v=>v.version===Number(to));if(!a||!b)return '<div class="note warn">请选择有效版本。</div>';const added=b.criteria.filter(c=>!a.criteria.some(old=>old.code===c.code)),retired=a.criteria.filter(c=>!b.criteria.some(next=>next.code===c.code));return `<h3>v${a.version} → v${b.version}</h3><div class="note info">标题：${pjEsc(a.title)} → ${pjEsc(b.title)}</div><div class="note info">描述：<p>${pjEsc(a.description)}</p><p>${pjEsc(b.description)}</p></div>${retired.map(c=>`<div class="note danger"><s>退役 ${c.code}：${pjEsc(c.text)}</s></div>`).join('')}${added.map(c=>`<div class="note ok">新增 ${c.code}：${pjEsc(c.text)}</div>`).join('')}${a.version===3&&b.version===4?'<div class="note warn">改写 C3 → C7：金额保留两位小数，按行项目舍入。新增 C8：文件名包含账期。</div>':''}${!added.length&&!retired.length?'<p class="muted small">没有验收标准变化。</p>':''}`;}
function pjCompareVersions(){document.getElementById('pj-version-diff').innerHTML=pjVersionDiff(pjVal('pj-version-old'),pjVal('pj-version-new'));pjIcons();}
function pjScopeSave(version){const r=pjRequirements.find(x=>x.id==='R-12'),p=pjProject(r.p),kind=pjVal('pj-scope-kind'),code=pjVal('pj-scope-criterion'),meta=document.getElementById('pj-impact-meta');if(pjReadonly(p))return pjError('项目只读。');if(r.version!==version)return pjError('需求已被他人更新到 v'+r.version+'，请关闭、刷新后重做（120440）。');if(!pjVal('pj-scope-title')||!pjVal('pj-scope-summary')||!pjVal('pj-reason')||(kind!=='retire'&&!pjVal('pj-scope-text')))return pjError('请填写标题、摘要、理由与标准文本。');if(meta.dataset.code!==code||meta.dataset.kind!==kind)return pjError('标准或修改方式已变化，请重新计算影响预览。');if(!document.getElementById('pj-stepup').checked)return pjError('请先完成重新认证（演示）。');const index=pjCriteria.findIndex(c=>c.code===code),old=pjCriteria[index],items=kind==='add'?[]:[...old.items];items.forEach(id=>{const w=pjWork.find(x=>x.id===id);if(pjVal('pj-impact-'+id)==='cancel'&&!['ACCEPTED','CANCELLED'].includes(w.s))w.s='CANCELLED';else w.stale=true;});r.version++;r.title=pjVal('pj-scope-title');r.description=pjVal('pj-scope-description');r.priority=pjVal('pj-scope-priority');if(kind==='retire'||kind==='rewrite')pjCriteria.splice(index,1);if(kind!=='retire')pjCriteria.push({code:'C'+(Math.max(8,...pjCriteria.map(c=>Number(c.code.slice(1))))+1),text:pjVal('pj-scope-text'),since:r.version,items:kind==='rewrite'?items:[]});r.standards=pjCriteria.length;pjVersions.push({version:r.version,at:'刚刚',title:r.title,description:r.description,criteria:pjCriteria.map(c=>({...c,items:[...c.items]})),record:'CH-演示-'+r.version});pjEvent(p,'范围变更至 v'+r.version+'：'+pjVal('pj-scope-summary'));closeModal();route();toast('新基线已生成，受影响工作项已处理（演示）');}

/* 派单提案 */
PAGES['dispatch']=(id)=>{const p=pjProject(id);if(!p)return head('派单','项目不存在','你可以返回项目列表。');pjCurrent=id;pjDispatchFilter='PROPOSED';const first=pjProposals.find(q=>q.p===id&&q.state==='PROPOSED');pjDispatchId=first?first.id:'';return head('项目编排 · '+p.code,'派单提案',`${TEAM.name} · ${p.policy==='AUTO'?'策略内自动生效，护栏命中需你确认':'主管提出建议，由你确认'}`,pjButton('返回项目',`go('project/${id}')`))+`<div id="pj-dispatch-body">${pjDispatchBody(p)}</div>`;};
TITLES['dispatch']='派单提案';NAVPARENT['dispatch']='projects';
function pjProposalState(q){return q.state==='PROPOSED'&&q.expires<=Date.now()?'EXPIRED':q.state;}
function pjDispatchBody(p){const labels={PROPOSED:'待处理',APPLIED:'已生效',OVERRIDDEN:'已改派',REJECTED:'已驳回',EXPIRED:'已过期'};const list=pjProposals.filter(q=>q.p===p.id&&pjProposalState(q)===pjDispatchFilter).sort((a,b)=>(a.expires||0)-(b.expires||0));const q=list.find(q=>q.id===pjDispatchId)||list[0];if(q)pjDispatchId=q.id;return `<div class="grid g12"><div class="c4 stack">${card('提案列表',`<div class="row wrap">${Object.keys(labels).map(k=>`<button class="chip ${pjDispatchFilter===k?'on':''}" onclick="pjDispatchFilterSet('${k}')">${labels[k]}</button>`).join('')}</div><div class="stack" style="margin-top:12px">${list.map(x=>`<button class="btn ${q&&x.id===q.id?'primary':''}" onclick="pjDispatchSelect('${x.id}')">${x.wi} · ${labels[pjProposalState(x)]}</button>`).join('')||'<div class="empty">当前没有这类提案。</div>'}</div>`)}${card('历史提案',pjTable(['工作项','处理','原因'],pjProposals.filter(x=>x.p===p.id&&pjProposalState(x)!=='PROPOSED').map(x=>`<tr><td>${x.wi}</td><td>${labels[pjProposalState(x)]}</td><td>${pjEsc(x.reason)}${x.guards.map(g=>`<div>G${g}：${pjGuards[g-1]}</div>`).join('')}</td></tr>`).join('')))}</div><div class="c8 stack">${q?pjDispatchDetail(p,q):card('提案详情','<div class="empty">选择一个提案查看推荐人、评分与护栏。主管只在进行中的项目为就绪工作项产生提案。</div>')}${card('自动派单护栏 G1–G9',`<div class="stack small">${pjGuards.map((text,i)=>`<div><b>G${i+1}</b> · ${text}</div>`).join('')}</div>`,{icon:'shield-check'})}</div></div>`;}
function pjDispatchDetail(p,q){const w=pjWork.find(w=>w.id===q.wi),pending=pjProposalState(q)==='PROPOSED',mins=Math.max(0,Math.ceil((q.expires-Date.now())/60000));return card('提案 '+q.id,`<div class="row wrap">${p.lead?who(p.lead):'<span>系统评分</span>'}<span class="badge b-info">${p.lead?'主管 Agent 提案':'系统评分'}</span>${pending?`<span class="badge b-warn">剩余 ${mins} 分钟</span>`:''}</div><p><a href="#/workitem/${w.id}"><b>${w.id} · ${pjEsc(w.t)}</b></a> · ${pjType[w.type]} · ${pjRisk[w.risk]}风险</p><p class="small">必需技能：${w.type==='DOC'?'文档、接口说明':w.id==='BIL-139'?'金额计算、边界测试':'接口实现、字段映射'} · 当前状态 ${S(w.s)}</p><div class="note info">推荐 ${PEOPLE[q.chosen].n} · ${q.chosen==='bo'?'82.60':'已处理快照'} 分。${pjEsc(q.reason)}</div>${q.guards.map(g=>`<div class="note warn">G${g} · ${pjGuards[g-1]}</div>`).join('')}${pjTable(['排名 / 候选','总分','技能 35%','首次验收 30%','成本 15%','负载 15%','多样性 5%'],pjScores.map((s,i)=>{const score=s.parts.reduce((n,v,j)=>n+v*[.35,.30,.15,.15,.05][j],0);return `<tr><td>${i+1} · ${who(s.key)}${OR(s.key)}</td><td>${score.toFixed(2)}</td>${s.parts.map((v,j)=>`<td title="${pjEsc(s.raw[j])}">${v}%<div class="progress"><i style="width:${v}%"></i></div><div class="muted xs">${s.raw[j]}</div></td>`).join('')}</tr>`;}).join(''))}<details><summary>不合格候选</summary><p class="small">Ada：活跃分派 3/3，达到并行上限（E8）。Echo：2/2 满载（E8）。Cy：没有执行者角色且已崩溃（E1 / E2）。Gale：孤儿，编制授权已到期（E12）。Atlas：不具执行者绑定，且主管自动派单不能推荐自身。</p></details><details><summary>复算说明</summary><p class="small">技能 35% + 同类型 90 天平滑首次验收 30% + 合格候选成本归一 15% + 当前负载 15% + 近 24 小时轮换 5%。分量取 0–10000 基点，得分四舍五入两位。</p><p class="code">scoring_version=s1 · inputs_digest=演示快照，无真实摘要</p><p class="muted xs">评分输入为演示快照；负载与成员表一致。Bo 总分 82.60，与主文件收件箱一致；满载候选先排除，再做成本归一。</p></details><div class="row wrap" style="margin-top:16px">${pjButton('确认派给 '+PEOPLE[q.chosen].n,`pjDispatchConfirm('${q.id}')`,'primary',!pending||pjReadonly(p)||w.s!=='READY',!pending?'已处理或过期，不能再次确认':w.s!=='READY'?'工作项不再就绪':'')}${pjButton('改派',`pjDispatchAction('${q.id}','override')`,'',!pending||pjReadonly(p))}${pjButton('驳回',`pjDispatchAction('${q.id}','reject')`,'danger',!pending||pjReadonly(p))}</div><p class="muted xs">派单只分配执行工作，不授予裁决权。你以 work_item_assign 权限确认；分派前重新核对状态。</p>`,{icon:'split'});}
function pjDispatchRender(){document.getElementById('pj-dispatch-body').innerHTML=pjDispatchBody(pjProject(pjCurrent));pjIcons();}
function pjDispatchFilterSet(state){pjDispatchFilter=state;pjDispatchId='';pjDispatchRender();}
function pjDispatchSelect(id){pjDispatchId=id;pjDispatchRender();}
function pjDispatchConfirm(id){const q=pjProposals.find(q=>q.id===id),w=pjWork.find(w=>w.id===q.wi),p=pjProject(q.p);if(pjProposalState(q)!=='PROPOSED')return toast('提案已被处理或已过期，请刷新。');if(pjReadonly(p)||w.s!=='READY')return toast('工作项不再就绪，不能分派。');q.state='APPLIED';q.reason='Morgan 确认派给 '+PEOPLE[q.chosen].n;w.who=q.chosen;w.s='CLAIMED';pjEvent(p,q.reason+' · '+w.id);pjDispatchRender();toast('派单已确认（演示），执行仍须通过项目闸门');}
function pjDispatchAction(id,kind){const q=pjProposals.find(q=>q.id===id),p=pjProject(q.p);pjModal(kind==='override'?'改派工作项':'驳回提案',`${kind==='override'?pjSelect('执行者（人与 Agent）','pj-assignee',p.members.filter(k=>k==='chen'||PEOPLE[k].role==='Agent 执行者'&&PEOPLE[k].origin!=='orphan').map(k=>[k,PEOPLE[k].n+' · '+PEOPLE[k].role]),'chen'):''}${pjField('理由（必填）','pj-reason')}<div class="note ${kind==='reject'?'danger':'warn'}">${kind==='override'?'人工改派将在 24 小时内触发 G8 护栏，防止自动策略覆盖你的意图。':'驳回仅关闭本提案，不会取消工作项。'}</div>`,pjButton('取消','closeModal()')+pjButton('确认',`pjDispatchActionSave('${id}','${kind}')`,kind==='reject'?'danger':'primary'));}
function pjDispatchActionSave(id,kind){const q=pjProposals.find(q=>q.id===id),p=pjProject(q.p),w=pjWork.find(w=>w.id===q.wi);if(pjReadonly(p)||pjProposalState(q)!=='PROPOSED')return pjError('提案已被处理或过期，请刷新。');if(!pjVal('pj-reason'))return pjError('请填写理由。');if(kind==='override'){if(w.s!=='READY')return pjError('工作项不再就绪，请刷新。');const k=pjVal('pj-assignee');if(!p.members.includes(k))return pjError('请选择项目内执行者。');w.who=k;w.s='CLAIMED';q.chosen=k;q.state='OVERRIDDEN';q.guards=[8];}else q.state='REJECTED';q.reason='Morgan：'+pjVal('pj-reason');pjEvent(p,'处理派单提案 '+q.id);closeModal();pjDispatchRender();toast('提案已处理（演示）');}

/* 主文件约定的两个创建入口 */
function newProjectWizard(){pjWizard={step:0,name:'',code:'',client:'',description:'',target:'',contact:'lee',receives:true,accepts:true,members:['morgan'],lead:'',budget:'800.00',notify:'80',repo:'',ai:true};try{const saved=JSON.parse(sessionStorage.getItem('pj-project-draft')||'null');if(saved)pjWizard={...pjWizard,...saved};}catch(pjIgnored){}pjWizardRender();}
function pjWizardRender(){const d=pjWizard,labels=['基本信息','开口与联系人','团队与模式','预算','确认'];let body='';
 if(d.step===0)body=`${pjField('项目名称（必填，最多 200 字）','pj-w-name',d.name,'text','maxlength="200"')}${pjField('项目代号（必填，创建后不可修改）','pj-w-code',d.code)}<p class="muted xs">大写字母开头，2–16 位，仅大写字母、数字、连字符；团队内唯一。</p>${pjField('甲方分组（可空）','pj-w-client',d.client)}${pjField('简介','pj-w-description',d.description,'text','maxlength="2000"')}${pjField('目标交付日（可空，不早于今天）','pj-w-target',d.target,'date')}`;
 if(d.step===1)body=`${pjSelect('来源开口','pj-w-channel',[['共享频道','共享频道'],['邮件','邮件'],['API','API']],d.channel||'共享频道')}${pjSelect('主联系人（可稍后补）','pj-w-contact',[['','稍后配置'],['lee','Lee · 甲方联系人']],d.contact)}<label class="row"><input type="checkbox" id="pj-w-receives" ${d.receives?'checked':''}>接收交付通知</label><label class="row"><input type="checkbox" id="pj-w-accepts" ${d.accepts?'checked':''} disabled>主联系人可签收（强制开启）</label><div class="note warn">没有可签收联系人将无法正式交付；甲方只通过开口提交、澄清、验收，不加入乙方执行团队。</div>`;
 if(d.step===2)body=`<div class="note info">你将成为本项目交付负责人。</div><div class="grid g12">${Object.keys(PEOPLE).filter(k=>PEOPLE[k].k!=='c').map(k=>`<label class="c6 row"><input type="checkbox" id="pj-w-member-${k}" ${d.members.includes(k)?'checked':''} ${k==='morgan'?'disabled':''}>${who(k)}${OR(k)}</label>`).join('')}</div>${pjSelect('主管 Agent','pj-w-lead',[['','未设置'],['lead','Atlas · 主管 Agent']],d.lead)}<label class="stack small">团队模式<select style="${pjInputStyle}" disabled><option>混编（默认）</option><option disabled>全自治（需创建后满足 P1–P5）</option></select></label><div class="muted xs">新项目默认混编；全 Agent 的成员组合也可使用混编模式。全自治需创建后满足 P1–P5 并由人重新认证切换。</div>`;
 if(d.step===3)body=`${pjField('预算上限（美元，可空 = 不限）','pj-w-budget',d.budget,'number','min="0.01" step="0.01"')}${pjField('通知阈值（50–95）','pj-w-notify',d.notify,'number','min="50" max="95"')}${pjField('主仓库远程地址（可空，不得含凭证）','pj-w-repo',d.repo)}<p class="muted xs">默认分支 main，保护 main；每台机器上的本地路径在机器页配置。</p><label class="row"><input type="checkbox" id="pj-w-ai" ${d.ai?'checked':''}>共享频道展示 AI 协作标签</label><div class="note info">80% 通知、100% 暂停新执行；不限预算不可启用全自治。</div>`;
 if(d.step===4)body=`<dl class="kv"><dt>项目</dt><dd>${pjEsc(d.name)} · ${pjEsc(d.code)}</dd><dt>甲方分组</dt><dd>${pjEsc(d.client||'未分组')}</dd><dt>开口 / 联系人</dt><dd>${pjEsc(d.channel)} · ${d.contact?'Lee':'尚未配置'}</dd><dt>团队</dt><dd>${d.members.map(k=>PEOPLE[k].n).join('、')} · 混编</dd><dt>主管</dt><dd>${d.lead?PEOPLE[d.lead].n:'未设置'}</dd><dt>预算</dt><dd>${d.budget?money(Number(d.budget)):'不限'} · ${d.notify}% 通知</dd><dt>仓库</dt><dd>${pjEsc(d.repo||'尚未配置')}</dd><dt>共享频道 AI 标签</dt><dd>${d.ai?'展示':'隐藏'}</dd></dl><div class="note info">正式产品会一次创建项目、档案、默认频道与角色绑定。当前仅在本脚本内创建演示记录；刷新恢复。</div>`;
 pjModal('新建项目 · '+(d.step+1)+'/5',`<div class="row wrap">${labels.map((t,i)=>`<span class="chip ${i===d.step?'on':''}">${i+1} ${t}</span>`).join('')}</div><div class="stack">${body}</div>`,pjButton('取消','closeModal()')+(d.step?pjButton('上一步','pjWizardMove(-1)'):'')+pjButton(d.step===4?'创建项目':'下一步',d.step===4?'pjWizardCreate()':'pjWizardMove(1)','primary').replace('<button ', '<button id="pj-wizard-next" '),true);
 const modal=document.getElementById('modal');if(modal){modal.querySelectorAll('input,select').forEach(el=>{el.addEventListener('input',pjWizardUpdate);el.addEventListener('change',pjWizardUpdate);});}pjWizardUpdate();
}
function pjWizardCapture(){const d=pjWizard;if(d.step===0){d.name=pjVal('pj-w-name');d.code=pjVal('pj-w-code');d.client=pjVal('pj-w-client');d.description=pjVal('pj-w-description');d.target=pjVal('pj-w-target');}if(d.step===1){d.channel=pjVal('pj-w-channel');d.contact=pjVal('pj-w-contact');d.receives=document.getElementById('pj-w-receives').checked;d.accepts=true;}if(d.step===2){d.members=Object.keys(PEOPLE).filter(k=>{const e=document.getElementById('pj-w-member-'+k);return e&&e.checked;});d.lead=pjVal('pj-w-lead');}if(d.step===3){d.budget=pjVal('pj-w-budget');d.notify=pjVal('pj-w-notify');d.repo=pjVal('pj-w-repo');d.ai=document.getElementById('pj-w-ai').checked;}}
function pjWizardUpdate(){pjWizardCapture();const d=pjWizard;let error='';if(d.step===0){if(!d.name||d.name.length>200)error='下一步前请填写项目名称（最多 200 字）。';else if(!/^[A-Z][A-Z0-9-]{1,15}$/.test(d.code))error='下一步前请填写合法的 2–16 位大写代号。';else if(pjProjects.some(p=>p.code===d.code))error='此代号已存在，请修改。';}if(d.step===2&&d.lead&&!d.members.includes(d.lead))error='请将主管 Agent 加入项目成员。';if(d.step===3){if(d.budget&&(!/^\d+(\.\d{1,2})?$/.test(d.budget)||Number(d.budget)<=0))error='预算须为正数且最多两位小数，或留空表示不限。';else if(!Number.isInteger(Number(d.notify))||Number(d.notify)<50||Number(d.notify)>95)error='通知阈值须为 50–95 的整数。';else if(d.repo&&(!/^(https:\/\/|ssh:\/\/|git@)[^\s]+$/.test(d.repo)||/\/\/[^/]*:[^/@]+@/.test(d.repo)||/^https:\/\/[^/]*@/.test(d.repo)))error='仓库地址格式无效或含凭证。';}const next=document.getElementById('pj-wizard-next');if(next)next.disabled=!!error;const hint=document.getElementById('pj-modal-error');if(hint)hint.textContent=error;try{sessionStorage.setItem('pj-project-draft',JSON.stringify(d));}catch(pjIgnored){}return !error;}
function pjWizardMove(delta){pjWizardCapture();const d=pjWizard;if(delta>0){if(d.step===0){if(!d.name||d.name.length>200||! /^[A-Z][A-Z0-9-]{1,15}$/.test(d.code))return pjError('请填写项目名称与合法代号。');if(pjProjects.some(p=>p.code===d.code||p.name===d.name&&p.client===d.client))return pjError('代号已存在，或同甲方下名称重复。');const today=new Date();const date=today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');if(d.target&&d.target<date)return pjError('目标交付日不能早于今天。');}if(d.step===2&&d.lead&&!d.members.includes(d.lead))return pjError('主管必须同时加入本项目成员。');if(d.step===3){if(d.budget&&(!/^\d+(\.\d{1,2})?$/.test(d.budget)||Number(d.budget)<=0)||!Number.isInteger(Number(d.notify))||Number(d.notify)<50||Number(d.notify)>95)return pjError('预算必须为正数且最多两位小数，阈值为 50–95 的整数。');if(d.repo&&(! /^(https:\/\/|ssh:\/\/|git@)[^\s]+$/.test(d.repo)||/\/\/[^/]*:[^/@]+@/.test(d.repo)))return pjError('远程地址必须为 HTTPS、SSH 或 git@ 地址，且不得含凭证。');}}d.step+=delta;try{sessionStorage.setItem('pj-project-draft',JSON.stringify(d));}catch(pjIgnored){}pjWizardRender();}
function pjWizardCreate(){const d=pjWizard;if(pjProjects.some(p=>p.code===d.code))return pjError('代号已存在，请返回修改。');const id='pj-new-'+(pjProjects.length+1),p={id,name:d.name,code:d.code,stage:'INTAKE',mode:'HYBRID',budget:[0,d.budget?Number(d.budget):Infinity],acc:[0,0],lead:d.lead||null,client:(d.contact?'Lee':'未配置联系人')+' · '+d.channel,health:'ok',members:[...d.members],policy:'MANUAL',parallel:3,description:d.description,target:d.target,ai:d.ai,roles:false,contacts:!!d.contact,repo:d.repo,notify:Number(d.notify),events:[],version:1};pjProjects.push(p);PROJECTS.push({...p,budget:[...p.budget],acc:[...p.acc]});try{sessionStorage.removeItem('pj-project-draft');}catch(pjIgnored){}closeModal();go('project/'+id);toast('项目已创建（内存演示），默认频道仅为模拟');}
function newWorkItem(){const p=pjProject(pjNewItemProject)||pjProject('p1');if(pjReadonly(p))return toast('项目只读，不能新建工作项');pjNewItemProject=p.id;pjModal('新建工作项 · '+p.code,`<div class="grid g12"><div class="c6 stack">${pjField('标题（必填）','pj-wi-title')}${pjSelect('类型','pj-wi-type',Object.keys(pjType).map(k=>[k,pjType[k]]),'FEATURE')}${pjSelect('风险','pj-wi-risk',Object.keys(pjRisk).map(k=>[k,pjRisk[k]]),'LOW')}${pjSelect('所属需求','pj-wi-requirement',[['','不关联需求'],...pjRequirements.filter(r=>r.p===p.id).map(r=>[r.id,r.id+' · '+r.title])],'')}<div class="stack small"><b>关联验收标准（仅 R-12 有明细）</b>${p.id==='p1'?pjCriteria.map(c=>`<label class="row"><input type="checkbox" id="pj-wi-c-${c.code}">${c.code} · ${c.text}</label>`).join(''):'<span class="muted">本项目暂无需求标准明细。</span>'}</div></div><div class="c6 stack"><b>依赖（必须是同项目工作项）</b>${pjWork.filter(w=>w.p===p.id&&w.s!=='CANCELLED').map(w=>`<label class="row small"><input type="checkbox" id="pj-wi-dep-${w.id}">${w.id} · ${w.t}</label>`).join('')}${pjField('估算（分钟，非负整数）','pj-wi-estimate','60','number','min="0" step="1"')}${pjSelect('派单方式','pj-wi-dispatch',[['proposal','主管 / 系统评分提案'],['manual','你手动分派'],['unassigned','暂不派单']],'proposal')}${pjSelect('执行者（手动分派时必选）','pj-wi-assignee',[['','请选择'],...p.members.filter(k=>k==='chen'||PEOPLE[k].role==='Agent 执行者'&&PEOPLE[k].origin!=='orphan').map(k=>[k,PEOPLE[k].n+' · '+PEOPLE[k].role])],'')}<div class="note info">未满足的依赖会使工作项阻塞。新建不代表执行已开始；主管仅在项目进行中对就绪项生成提案。</div></div></div>`,pjButton('取消','closeModal()')+pjButton('创建工作项','pjWorkItemCreate()','primary'),true);}
function pjWorkItemCreate(){const p=pjProject(pjNewItemProject),title=pjVal('pj-wi-title'),req=pjVal('pj-wi-requirement'),estimate=Number(pjVal('pj-wi-estimate')),mode=pjVal('pj-wi-dispatch'),assignee=pjVal('pj-wi-assignee');if(pjReadonly(p))return pjError('项目只读。');if(!title||title.length>500||!Number.isInteger(estimate)||estimate<0)return pjError('请填写标题（最多 500 字）与非负整数估算。');const criteria=pjCriteria.filter(c=>{const e=document.getElementById('pj-wi-c-'+c.code);return e&&e.checked;});if(criteria.length&&req!=='R-12')return pjError('所选验收标准属于 R-12，请修改所属需求或取消标准选择。');if(mode==='manual'&&!assignee)return pjError('手动派单需选择执行者。');const deps=pjWork.filter(w=>{const e=document.getElementById('pj-wi-dep-'+w.id);return e&&e.checked;});const blocked=deps.some(w=>w.s!=='ACCEPTED'),id=p.code+'-'+(Math.max(0,...pjWork.filter(w=>w.p===p.id).map(w=>Number(w.id.split('-').pop())||0))+1),r=pjRequirements.find(r=>r.id===req);const w={id,t:title,p:p.id,type:pjVal('pj-wi-type'),risk:pjVal('pj-wi-risk'),s:blocked?'BLOCKED':mode==='manual'?'CLAIMED':'READY',who:mode==='manual'?assignee:null,l:0,br:0,cost:0,requirement:req||'—',estimate,baseline:r?'v'+r.version:'—',criteria:criteria.map(c=>c.code),dependencies:deps.map(w=>w.id),stale:false};pjWork.push(w);WI.push({...w});criteria.forEach(c=>c.items.push(id));pjEvent(p,'创建工作项 '+id);closeModal();pjRefresh();toast('已创建 '+id+(mode==='proposal'?'；派单提案等待主管 / 系统生成':''));}
